import { describe, expect, it, vi } from "vitest";
import { createCompanionBridge, type CompanionOwner } from "./companionBridge";
import type { Session } from "../../sessions/model/session";

const PNG = "iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mP8/x8AAusB9Y9JZCkAAAAASUVORK5CYII=";
// Generated by cjpeg/cwebp from a 1×1 red PPM. WEBP is a lossy VP8 frame.
const JPEG = "";
const WEBP = "UklGRjwAAABXRUJQVlA4IDAAAADQAQCdASoBAAEAAUAmJaACdLoB+AADsAD+8ut//NgVzXPv9//S4P0uD9Lg/9KQAAA=";

function image(id: string, name: string, mimeType: string, data: string) {
  return { id, name, mimeType, size: atob(data).length, width: 1, height: 1 };
}

function fixture(queued = false) {
  const session: Session = {
    id: "phone-test", harness: "codex", model: "test", modelSettings: {},
    runtimeMode: "supervised", title: "Test", cwd: "/tmp/companion-test", blocks: [],
  };
  let turn = 1;
  const owner: CompanionOwner = {
    flush: vi.fn(), sessions: () => [session], eligible: () => true, turn: () => turn,
    queuedFollowUps: queued,
    send: vi.fn(async (_id, prompt, attachments, requestId) => {
      if (queued) return "queued" as const;
      session.blocks.push({ id: requestId, role: "user", text: prompt, attachments });
      turn += 1;
      return true;
    }),
    approve: vi.fn(), stop: vi.fn(),
  };
  const bridge = createCompanionBridge(owner, "epoch");
  return { bridge, input: () => ({ epoch: "epoch", sessionId: session.id, turn }), owner, session };
}

function namespacedId(peer: string, raw: string) {
  return `${peer.repeat(64)}-${raw.repeat(32)}`;
}

async function stage(
  bridge: ReturnType<typeof createCompanionBridge>,
  input: () => { epoch: string; sessionId: string; turn: number },
  uploadId: string,
  attachment: ReturnType<typeof image>,
  data: string,
  split = false,
) {
  const bytes = atob(data);
  const chunks = split
    ? [{ offset: 0, data: btoa(bytes.slice(0, 2)) }, { offset: 2, data: btoa(bytes.slice(2)) }]
    : [{ offset: 0, data }];
  for (const chunk of chunks) {
    await expect(bridge.handle(`${uploadId}-u0-${chunk.offset}`, "sessions.attachment.upload", {
      ...input(), uploadId, ...attachment, ...chunk,
    })).resolves.toEqual({ accepted: true });
  }
}

describe("actual host device namespaces", () => {
  it("sends, retries after a lost receipt, and sends an image-only message with real host ID lengths", async () => {
    const { bridge, input, owner } = fixture();
    const first = namespacedId("a", "b");
    const screenshot = image("image", "screen.png", "image/png", PNG);
    await stage(bridge, input, first, screenshot, PNG, true);
    const command = { ...input(), uploadId: first, text: "Read this", attachments: [screenshot] };
    await expect(bridge.handle(first, "sessions.send", command)).resolves.toMatchObject({ accepted: true });
    // The owner advanced its turn; the exact final envelope still returns its receipt.
    await expect(bridge.handle(first, "sessions.send", command)).resolves.toMatchObject({ accepted: true });
    expect(owner.send).toHaveBeenCalledTimes(1);

    const imageOnly = namespacedId("a", "c");
    const second = image("image-only", "screen.png", "image/png", PNG);
    await stage(bridge, input, imageOnly, second, PNG);
    await expect(bridge.handle(imageOnly, "sessions.send", {
      ...input(), uploadId: imageOnly, text: "", attachments: [second],
    })).resolves.toMatchObject({ accepted: true });
    expect(owner.send).toHaveBeenLastCalledWith("phone-test", "", expect.any(Array), `companion:epoch:${imageOnly}`);

    const transcript = await bridge.handle("read", "sessions.read", { sessionId: "phone-test" });
    expect(transcript).toMatchObject({ blocks: expect.arrayContaining([
      expect.objectContaining({ attachments: [expect.objectContaining({ name: "screen.png" })] }),
    ]) });
    expect(JSON.stringify(transcript)).not.toContain(PNG);
  });

  it("keeps two full peer namespaces separate when the phone reuses its raw ID", async () => {
    const { bridge, input, owner } = fixture();
    const attachment = image("image", "screen.png", "image/png", PNG);
    for (const uploadId of [namespacedId("a", "d"), namespacedId("c", "d")]) {
      await stage(bridge, input, uploadId, attachment, PNG);
      await bridge.handle(uploadId, "sessions.send", { ...input(), uploadId, text: uploadId.slice(0, 1), attachments: [attachment] });
    }
    expect(owner.send).toHaveBeenCalledTimes(2);
    expect(vi.mocked(owner.send).mock.calls.map(call => call[3])).toEqual([
      `companion:epoch:${namespacedId("a", "d")}`,
      `companion:epoch:${namespacedId("c", "d")}`,
    ]);
  });

  it("queues a real-length image envelope without conflating the queue acknowledgement with delivery", async () => {
    const { bridge, input, owner, session } = fixture(true);
    session.busy = true;
    const uploadId = namespacedId("a", "e");
    const attachment = image("queued", "screen.png", "image/png", PNG);
    await stage(bridge, input, uploadId, attachment, PNG);
    await expect(bridge.handle(uploadId, "sessions.send", {
      ...input(), uploadId, text: "Queue this", attachments: [attachment],
    })).resolves.toMatchObject({ accepted: true, delivery: "queued", queueId: `companion_epoch_${uploadId}` });
    expect(owner.send).toHaveBeenCalledOnce();
  });

  it("accepts actual JPEG and lossy VP8 WebP dimensions", async () => {
    const { bridge, input, owner } = fixture();
    for (const [mimeType, name, data] of [["image/jpeg", "photo.jpg", JPEG], ["image/webp", "photo.webp", WEBP]] as const) {
      const uploadId = namespacedId("f", mimeType === "image/jpeg" ? "g" : "h");
      const attachment = image(`image-${mimeType.slice(6)}`, name, mimeType, data);
      await stage(bridge, input, uploadId, attachment, data);
      await expect(bridge.handle(uploadId, "sessions.send", {
        ...input(), uploadId, text: name, attachments: [attachment],
      })).resolves.toMatchObject({ accepted: true });
    }
    expect(owner.send).toHaveBeenCalledTimes(2);
  });
});
